      required: false,
      default: 'md',
    },
    {
      name: 'children',
      description: '`<DataListItem>` rows, as an alternative to `items`.',
      type: 'ReactNode',
      required: false,
    },
  ],
  tokens: [
    '--cascivo-color-text',
    '--cascivo-color-text-subtle',
