    },
    {
      title: 'Vertical — value under its label, not "items stacked vertically"',
      description:
        'Both modes stack the items vertically. `orientation` moves the VALUE: beside its label (horizontal) or under it (vertical).',
      code: `<DataList\n  orientation="vertical"\n  items={[\n    { label: 'Region', value: 'fra1' },\n    { label: 'Branch', value: 'main' },\n  ]}\n/>`,
    },
